  const openNotification=(destination:NotificationDestination)=>{if(destination.itemId&&destination.itemKind&&destination.envelopeId){navigation.open({view:"Cronograma",flow:null,overlay:"planningDetail",context:{envelopeId:destination.envelopeId,itemId:destination.itemId,kind:destination.itemKind}},true);return;}setSearch("");setFilter("Todos");navigation.open({view:destination.page,overlay:null,flow:null,step:0,movementId:destination.movementId||null,movementEnvelopeId:null,reminderEnvelopeId:destination.envelopeId||null},true);window.scrollTo({top:0});};
  if((cloudEnabled&&authLoading)||(!cloudReady&&(!cloudEnabled||authUser)))return <div className="auth-screen"><section className="auth-card"><BrandLogo />{store.error?<><h1>No se pudieron cargar tus datos</h1><p>{store.error}</p><p>Tus datos guardados se conservan. Las escrituras están pausadas.</p>{cloudEnabled&&<button className="primary wide" onClick={()=>void store.retry()}>Volver a intentar</button>}<button className="secondary wide" onClick={store.downloadBackup}>Descargar copia de respaldo</button>{authUser&&<button className="auth-switch" onClick={()=>void supabase?.auth.signOut()}>Cerrar sesión</button>}</>:<><div className="auth-spinner"/><h1>{authLoading?"Conectando con tu cuenta":"Cargando tus datos"}</h1><p>Un momento, estamos preparando tu espacio financiero.</p></>}</section></div>;
  if(cloudEnabled&&!authUser)return <div className="auth-screen"><form className="auth-card" onSubmit={submitAuth}><BrandLogo /><div className="overline">TUS FINANZAS, A TU MANERA</div><h1>{authMode==="login"?"Bienvenido de nuevo":"Crea tu cuenta"}</h1><p>{authMode==="login"?"Inicia sesión para sincronizar tus sobres y movimientos.":"Tus datos se guardarán de forma privada en tu cuenta."}</p><label htmlFor="finance-correo-electr-nico-1">Correo electrónico</label><input id="finance-correo-electr-nico-1" type="email" autoComplete="email" required value={authEmail} onChange={e=>setAuthEmail(e.target.value)} placeholder="tu@correo.com"/><label htmlFor="finance-contrase-a-2">Contraseña</label><input id="finance-contrase-a-2" type="password" minLength={6} autoComplete={authMode==="login"?"current-password":"new-password"} required value={authPassword} onChange={e=>setAuthPassword(e.target.value)} placeholder="Al menos 6 caracteres"/>{(authError||store.error)&&<div className="auth-error">{authError||store.error}</div>}<button className="primary wide" disabled={authBusy}>{authBusy?"Un momento…":authMode==="login"?"Iniciar sesión":"Crear cuenta"}</button><button type="button" className="auth-switch" onClick={()=>{setAuthMode(authMode==="login"?"signup":"login");setAuthError("")}}>{authMode==="login"?"¿Primera vez? Crea una cuenta":"Ya tienes cuenta? Inicia sesión"}</button></form></div>;

