    {view==="Cronograma"&&<PlanningCalendar envelopes={data.envelopes} today={today().slice(0,10)} date={navigation.calendarDate||today().slice(0,10)} scale={navigation.calendarScale||"Mes"} onChange={(calendarDate,calendarScale)=>navigation.open({calendarDate,calendarScale},true)} display={display} privateMode={data.hidden} onSelect={entry=>{if(entry.item)navigation.open({overlay:"planningDetail",context:{envelopeId:entry.envelopeId,itemId:entry.item.id,kind:entry.item.kind}});else {const envelope=data.envelopes.find(e=>e.id===entry.envelopeId);if(envelope)navigation.open({overlay:"goal",context:{...envelope,returnToPlanning:true}});}}}/>}
