    {view==="Configuración"&&<SettingsGroups><h2>Inicio</h2><p className="flow-intro">Configura cómo luce y se comporta la pantalla de Inicio.</p><div className="setting-row"><div><b id="home-header-label">Mantener fijo el encabezado</b><small id="home-header-hint">Mantiene a mano el tamaño de interfaz, tema, visibilidad de montos, calendario y notificaciones al desplazarte por Inicio.</small></div><button type="button" role="switch" aria-checked={data.homeHeaderPinned!==false} aria-labelledby="home-header-label" aria-describedby="home-header-hint" className={`switch ${data.homeHeaderPinned!==false?"on":""}`} onClick={()=>setData(d=>({...d,homeHeaderPinned:d.homeHeaderPinned===false}))}>{data.homeHeaderPinned!==false?"Sí":"No"}</button></div><h2>Apariencia</h2><label htmlFor="appearance-theme">Tema de Finanzas</label><select id="appearance-theme" value={mode} onChange={event=>setMode(event.target.value as ColorMode)}>{Object.entries(themeNames).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><h2>Privacidad</h2><div className="setting-row"><div><b>Vista privada</b><small>Oculta los montos en la pantalla.</small></div><button className={`switch ${data.hidden?"on":""}`} onClick={()=>setData(d=>({...d,hidden:!d.hidden}))}>{data.hidden?"Sí":"No"}</button></div><h2>Vista de sobres</h2><ProximityVisibility visible={data.showProximity!==false} onChange={showProximity=>setData(d=>({...d,showProximity}))}/><EnvelopeViewPreferences value={data} onChange={value=>setData(d=>({...d,...value}))}/><h2>Notificaciones y sonidos</h2><NotificationSettings state={data.notifications} onChange={updateNotifications}/><h2>Preferencias · Registro de ingresos</h2><IncomePreferenceSettings value={data.incomePreferences} accounts={data.accounts} onSave={incomePreferences=>setData(d=>({...d,incomePreferences}))}/><h2>Nombres y registro</h2><MovementNameSettings envelopes={data.envelopes} today={today().slice(0,10)} display={display} privateMode={data.hidden} value={naming} onChange={(kind,settings)=>setData(d=>({...d,naming:{...normalizeNaming(d),[kind]:settings}}))}/><h2>Categorías de gastos</h2><ExpenseCategoryManager categories={categories} onSave={saveCategory}/><h2>Datos y respaldo</h2><p className="flow-intro">{syncLabel[syncStatus]}</p><div className="setting-row"><div><b>Copia de respaldo</b><small>Descarga tus datos y las copias pendientes conservadas en este navegador.</small></div><button className="secondary" onClick={store.downloadBackup}>Descargar</button></div><button className="danger-link" disabled={cloudEnabled&&(store.pending||syncStatus!=="synced")} onClick={clearLocalData}>{cloudEnabled?"Limpiar copia local":"Reiniciar datos locales"}</button>{cloudEnabled&&<p className="flow-intro">Limpiar la copia local no modifica saldos ni movimientos en Supabase. Primero deben estar sincronizados los cambios.</p>}<button className="danger-link" disabled={!cloudReady||(cloudEnabled&&(store.pending||syncStatus!=="synced"))} onClick={()=>navigation.open({overlay:"reset"})}>Borrar movimientos y restablecer saldos</button><h2>Comentarios</h2><button className="secondary" onClick={()=>navigation.open({overlay:"feedback"})}>Enviar sugerencia</button></SettingsGroups>}
